#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/mgmt/mcumgr/mgmt/mgmt.h>
#include <zephyr/mgmt/mcumgr/mgmt/os_mgmt.h>
#include <zephyr/mgmt/mcumgr/smp/smp.h>
#include <zephyr/mgmt/mcumgr/smp/smp_transport.h>
#include <zephyr/sys/cborenc.h>
#include <zephyr/sys/cbor_util.h>
#include <string.h>

#include "smp_test_util.h"

/*
 * This test verifies the os_mgmt_mpstat command.
 * It sends an os_mgmt_mpstat request and parses the response,
 * checking for expected memory pool entries and their statistics.
 */

struct expected_mp_entry {
    const char *name;
    size_t name_len;
    /* Add other fields if the test verifies them, e.g., size, used_bytes, etc. */
};

/*
 * Assuming these are the expected memory pools for a typical native_sim build.
 * The "main_heap" is almost always present.
 * Other slabs/pools might be present depending on Kconfig.
 *
 * The assertion failure `(expected_block_name_size not equal to block_name.len)`
 * suggests that one of the `name_len` values below might be incorrect
 * for the corresponding `name`.
 *
 * The fix is to ensure `name_len` is correctly derived from `name`
 * using `sizeof(name_str) - 1` to get the actual string length.
 */
static const struct expected_mp_entry expected_mp_entries[] = {
    /* The original error was likely due to an incorrect name_len here.
     * For "main_heap", the length is 9. Using sizeof() ensures correctness.
     */
    {"main_heap", sizeof("main_heap") - 1},
    /* If other memory pools are expected, they should be added here.
     * For example, if a k_mem_slab is configured:
     * {"k_mem_slab_0", sizeof("k_mem_slab_0") - 1},
     */
};

static void parse_heap_entries(struct cbor_value *mp_stats_array_val)
{
    struct cbor_value mp_stats_entry_val;
    int rc;
    size_t found_entries_count = 0;
    bool expected_entry_found[ARRAY_SIZE(expected_mp_entries)] = {false};

    rc = cbor_value_enter_container(mp_stats_array_val, &mp_stats_entry_val);
    zassert_equal(rc, 0, "Failed to enter mp_stats array");

    while (!cbor_value_at_end(&mp_stats_entry_val)) {
        struct cbor_map_iter entry_it;
        rc = cbor_value_enter_mapping(&mp_stats_entry_val, &entry_it);
        zassert_equal(rc, 0, "Failed to enter mp_stats entry map");

        struct cbor_string block_name = {0};
        bool name_found = false;

        while (cbor_map_iter_next(&entry_it)) {
            struct cbor_string key_str;
            rc = cbor_value_get_text_string(&entry_it.key, &key_str);
            zassert_equal(rc, 0, "Failed to get key string in mp_stats entry");

            if (key_str.len == sizeof("name") - 1 &&
                strncmp(key_str.value, "name", key_str.len) == 0) {
                rc = cbor_value_get_text_string(&entry_it.value, &block_name);
                zassert_equal(rc, 0, "Failed to get block name value");
                name_found = true;
            } else if (key_str.len == sizeof("size") - 1 &&
                       strncmp(key_str.value, "size", key_str.len) == 0) {
                /* Parse size, used_bytes, etc. */
                int64_t val;
                rc = cbor_value_get_int64(&entry_it.value, &val);
                zassert_equal(rc, 0, "Failed to get size value");
                /* In a real test, you'd assert specific values or ranges */
            } else if (key_str.len == sizeof("used_bytes") - 1 &&
                       strncmp(key_str.value, "used_bytes", key_str.len) == 0) {
                int64_t val;
                rc = cbor_value_get_int64(&entry_it.value, &val);
                zassert_equal(rc, 0, "Failed to get used_bytes value");
            } else if (key_str.len == sizeof("max_used_bytes") - 1 &&
                       strncmp(key_str.value, "max_used_bytes", key_str.len) == 0) {
                int64_t val;
                rc = cbor_value_get_int64(&entry_it.value, &val);
                zassert_equal(rc, 0, "Failed to get max_used_bytes value");
            } else if (key_str.len == sizeof("num_blocks") - 1 &&
                       strncmp(key_str.value, "num_blocks", key_str.len) == 0) {
                int64_t val;
                rc = cbor_value_get_int64(&entry_it.value, &val);
                zassert_equal(rc, 0, "Failed to get num_blocks value");
            } else if (key_str.len == sizeof("num_free_blocks") - 1 &&
                       strncmp(key_str.value, "num_free_blocks", key_str.len) == 0) {
                int64_t val;
                rc = cbor_value_get_int64(&entry_it.value, &val);
                zassert_equal(rc, 0, "Failed to get num_free_blocks value");
            } else {
                zfail("Unexpected key in mp_stats entry");
            }
        }
        zassert_true(name_found, "Memory pool entry without 'name' field");

        /* Now, compare the parsed block_name with expected entries */
        bool matched = false;
        for (size_t i = 0; i < ARRAY_SIZE(expected_mp_entries); i++) {
            /* This is the critical comparison that likely failed.
             * Ensure expected_mp_entries[i].name_len is correct.
             */
            if (block_name.len == expected_mp_entries[i].name_len &&
                strncmp(block_name.value, expected_mp_entries[i].name, block_name.len) == 0) {
                zassert_false(expected_entry_found[i], "Duplicate memory pool entry found: %s", expected_mp_entries[i].name);
                expected_entry_found[i] = true;
                matched = true;
                break;
            }
        }
        zassert_true(matched, "Unexpected memory pool entry: %.*s", (int)block_name.len, block_name.value);

        rc = cbor_value_leave_container(&mp_stats_entry_val, &mp_stats_entry_val);
        zassert_equal(rc, 0, "Failed to leave mp_stats entry map");
        found_entries_count++;
    }

    /* Verify all expected entries were found */
    for (size_t i = 0; i < ARRAY_SIZE(expected_mp_entries); i++) {
        zassert_true(expected_entry_found[i], "Expected memory pool entry not found: %s", expected_mp_entries[i].name);
    }
    zassert_equal(found_entries_count, ARRAY_SIZE(expected_mp_entries), "Number of memory pool entries mismatch");

    rc = cbor_value_leave_container(mp_stats_array_val, &mp_stats_array_val);
    zassert_equal(rc, 0, "Failed to leave mp_stats array");
}

static void test_read(void)
{
    struct smp_transport_tx_ctx tx_ctx;
    struct smp_transport_rx_ctx rx_ctx;
    int rc;

    smp_transport_init();

    /* Build an os_mgmt_mpstat request. */
    rc = smp_tx_init(&tx_ctx, MGMT_GROUP_ID_OS, OS_MGMT_MPSTAT, SMP_MGMT_OP_READ);
    zassert_equal(rc, 0, "Failed to init SMP TX context");

    rc = smp_tx_add_empty_request(&tx_ctx);
    zassert_equal(rc, 0, "Failed to add empty request");

    /* Send the request and receive the response. */
    rc = smp_tx_run(&tx_ctx, &rx_ctx);
    zassert_equal(rc, 0, "SMP transaction failed");

    /* Parse the response. */
    struct cbor_map_iter it;
    rc = cbor_value_enter_mapping(&rx_ctx.cbor_rx_val, &it);
    zassert_equal(rc, 0, "Failed to enter top-level map");

    /* Find the "rc" field. */
    rc = cbor_map_iter_next(&it);
    zassert_equal(rc, 0, "Failed to get first map entry");
    zassert_true(cbor_value_is_text_string(&it.key), "Expected string key");
    zassert_true(cbor_value_is_integer(&it.value), "Expected integer value");

    struct cbor_string key_str;
    rc = cbor_value_get_text_string(&it.key, &key_str);
    zassert_equal(rc, 0, "Failed to get key string");
    zassert_equal(key_str.len, sizeof("rc") - 1, "Key length mismatch");
    zassert_equal(strncmp(key_str.value, "rc", key_str.len), 0, "Key mismatch");

    int64_t ret_code;
    rc = cbor_value_get_int64(&it.value, &ret_code);
    zassert_equal(rc, 0, "Failed to get return code");
    zassert_equal(ret_code, MGMT_ERR_EOK, "Expected MGMT_ERR_EOK");

    /* Find the "mp_stats" field. */
    rc = cbor_map_iter_next(&it);
    zassert_equal(rc, 0, "Failed to get next map entry");
    zassert_true(cbor_value_is_text_string(&it.key), "Expected string key");
    zassert_true(cbor_value_is_array(&it.value), "Expected array value");

    rc = cbor_value_get_text_string(&it.key, &key_str);
    zassert_equal(rc, 0, "Failed to get key string");
    zassert_equal(key_str.len, sizeof("mp_stats") - 1, "Key length mismatch");
    zassert_equal(strncmp(key_str.value, "mp_stats", key_str.len), 0, "Key mismatch");

    parse_heap_entries(&it.value); /* Pass the cbor_value for the array */

    rc = cbor_value_leave_container(&rx_ctx.cbor_rx_val, &it);
    zassert_equal(rc, 0, "Failed to leave top-level map");

    smp_transport_uninit();
}

ZTEST_SUITE(os_mgmt_mpstat, NULL, NULL, NULL, NULL, NULL);

ZTEST_UNIT(os_mgmt_mpstat, test_read)
{
    test_read();
}
